package main

import (
	"encoding/json"
	"os"
)

type input struct {
	Host string
	Port int
}

func main() {
 var cases []input
 if err:=json.Unmarshal([]byte(os.Args[1]), &cases); err!=nil { panic(err) }
 enc:=json.NewEncoder(os.Stdout)
 for _, in:=range cases {
  var out any
  address,ok:=JoinEndpoint(in.Host,in.Port)
  	out=struct{Address string;OK bool}{address,ok}
  if err:=enc.Encode(out); err!=nil { panic(err) }
 }
}
